/**
 * Synthetic problems for format inference (#115). Statements and samples are written for
 * this project to mirror common input/output shapes; none is Baekjoon text. `expect` is
 * the format a person would write (names included).
 */
import type { Sample } from '@/boj/problem';

export interface InferProblem {
  name: string;
  category: string;
  input: string;
  output: string;
  samples: Sample[];
  expect: unknown;
}

const s = (input: string, output: string): Sample => ({ input, output });
const p = (name: string, type: string, extra: Record<string, unknown> = {}) => ({ name, type, ...extra });

